CREATE VIEW fixture_structure AS SELECT c.oid,c.relname,c.relowner,c.relrowsecurity,c.relforcerowsecurity, (SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0) columns, (SELECT jsonb_agg(pg_get_expr(adbin,adrelid) ORDER BY adnum) FROM pg_attrdef WHERE adrelid=c.oid) defaults, (SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid=c.oid) constraints, (SELECT jsonb_agg(pg_get_triggerdef(oid) ORDER BY tgname) FROM pg_trigger WHERE tgrelid=c.oid) triggers, (SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname) FROM pg_policies p WHERE schemaname='public' AND tablename=c.relname) policies FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('_mprf_repoint_plan','manta_csv_stage','manta_remap_queue_20260323','mantas_bisect_log','mantas_extra_photos','mantas_extra_quarantine','mprf_manta_reconstruction_candidates_20260322','stg_mprf_sightings_full');
CREATE TEMP TABLE structure_before AS SELECT * FROM fixture_structure;
CREATE TEMP TABLE acl_before AS SELECT c.oid,(SELECT jsonb_agg(to_jsonb(a) ORDER BY grantor,grantee,privilege_type) FROM aclexplode(c.relacl) a) acl FROM pg_class c JOIN structure_before b USING(oid);
CREATE TEMP TABLE content_before(name text,rows bigint,fingerprint text);
